-- Tables with RLS enabled and no policy below are service-role only.

-- projects still carries the legacy "Users can manage their own projects" FOR
-- ALL policy beside its per-command policies (both permissive, OR-ed), as in
-- Rune 1.x. Manuscript tables use per-command policies for `authenticated` only.

create policy "chapters: delete own" on public.chapters
  as permissive for delete to authenticated
  using ((EXISTS ( SELECT 1
   FROM (manuscripts m
     JOIN projects p ON ((p.id = m.project_id)))
  WHERE ((m.id = chapters.manuscript_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))));

create policy "chapters: insert own" on public.chapters
  as permissive for insert to authenticated
  with check ((EXISTS ( SELECT 1
   FROM (manuscripts m
     JOIN projects p ON ((p.id = m.project_id)))
  WHERE ((m.id = chapters.manuscript_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))));

create policy "chapters: select own" on public.chapters
  as permissive for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM (manuscripts m
     JOIN projects p ON ((p.id = m.project_id)))
  WHERE ((m.id = chapters.manuscript_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))));

create policy "chapters: update own" on public.chapters
  as permissive for update to authenticated
  using ((EXISTS ( SELECT 1
   FROM (manuscripts m
     JOIN projects p ON ((p.id = m.project_id)))
  WHERE ((m.id = chapters.manuscript_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))))
  with check ((EXISTS ( SELECT 1
   FROM (manuscripts m
     JOIN projects p ON ((p.id = m.project_id)))
  WHERE ((m.id = chapters.manuscript_id) AND (p.user_id = ( SELECT auth.uid() AS uid))))));

