-- ── Triggers ────────────────────────────────────────────────────────────────
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE TRIGGER chapters_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON chapters FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER profiles_protect_billing_columns BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_billing_columns();
CREATE TRIGGER profiles_protect_is_admin BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION protect_is_admin();
CREATE TRIGGER trg_project_manuscript AFTER INSERT ON projects FOR EACH ROW EXECUTE FUNCTION create_project_manuscript();
CREATE TRIGGER scene_version_trigger BEFORE UPDATE ON scenes FOR EACH ROW EXECUTE FUNCTION increment_scene_version();
CREATE TRIGGER scenes_fill_manuscript_id BEFORE INSERT ON scenes FOR EACH ROW EXECUTE FUNCTION fill_scene_manuscript_id();
CREATE TRIGGER scenes_forbid_manuscript_reassignment BEFORE UPDATE OF manuscript_id ON scenes FOR EACH ROW EXECUTE FUNCTION forbid_manuscript_reassignment();
CREATE TRIGGER trg_scene_updated AFTER UPDATE ON scenes FOR EACH ROW EXECUTE FUNCTION bump_project_updated_at();
CREATE TRIGGER user_pricing_entitlements_touch_updated_at BEFORE UPDATE ON user_pricing_entitlements FOR EACH ROW EXECUTE FUNCTION touch_pricing_entitlement_updated_at();

